#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Import the telegram utilities
const { sendMessage } = require('../event_handler/tools/telegram.js');

// Read the briefing
const briefingPath = path.join(__dirname, 'sterling_briefing.md');
const briefing = fs.readFileSync(briefingPath, 'utf8');

// Convert markdown to HTML (simple conversion for Telegram)
function mdToTelegramHtml(md) {
  return md
    // Headers
    .replace(/^# (.+)$/gm, '<b>$1</b>')
    .replace(/^## (.+)$/gm, '<b>$1</b>')
    .replace(/^### (.+)$/gm, '<b>$1</b>')
    // Bold
    .replace(/\*\*(.+?)\*\*/g, '<b>$1</b>')
    // Italic
    .replace(/\*(.+?)\*/g, '<i>$1</i>')
    .replace(/_(.+?)_/g, '<i>$1</i>')
    // Code
    .replace(/`(.+?)`/g, '<code>$1</code>')
    // Links
    .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>')
    // Horizontal rules
    .replace(/^---$/gm, '—————————————————')
    // Remove markdown formatting that doesn't translate
    .replace(/^>/gm, '▶︎')
    .trim();
}

async function main() {
  const botToken = process.env.TELEGRAM_BOT_TOKEN;
  const chatId = process.env.TELEGRAM_CHAT_ID;

  if (!botToken || !chatId) {
    console.error('❌ Error: TELEGRAM_BOT_TOKEN or TELEGRAM_CHAT_ID not set');
    console.error('Available env vars:', Object.keys(process.env).filter(k => k.includes('TELEGRAM')).join(', '));
    process.exit(1);
  }

  console.log('📱 Posting Sterling Intelligence Briefing to Telegram...');
  console.log(`📍 Chat ID: ${chatId.slice(0, 5)}...`);

  try {
    const htmlMessage = mdToTelegramHtml(briefing);

    await sendMessage(botToken, chatId, htmlMessage, { disablePreview: false });

    console.log('✅ Briefing posted successfully!');
  } catch (error) {
    console.error('❌ Error posting to Telegram:', error.message);
    if (error.response) {
      console.error('Response:', error.response.data);
    }
    process.exit(1);
  }
}

main();

